//go:build integration && !localstack

package integration

import (
	"context"
	"fmt"
	"slices"
	"testing"
	"time"

	pb "github.com/kevlarcon/weft/proto/weftpb"
	"github.com/kevlarcon/weft/store"
)

// TestBuckets_DefaultSeeded asserts migrations 020/021/022 left
// the default bucket with the shape the Go layer expects. Looks up
// by label (the surrogate primary key is generated by 022 and
// isn't stable across rebuilds).
func TestBuckets_DefaultSeeded(t *testing.T) {
	db := openTestStore(t)
	defer db.Close()

	b, ok, err := db.GetBucketByLabel("default")
	if err != nil {
		t.Fatalf("GetBucketByLabel(default): %v", err)
	}
	if !ok {
		t.Fatal("default bucket missing — migration 020 did not seed it")
	}
	if b.ID <= 0 {
		t.Errorf("default.id: got %d, want a positive surrogate", b.ID)
	}
	if b.Label != "default" {
		t.Errorf("default.label: got %q, want default", b.Label)
	}

	if b.TargetIngestingCount != 2 {
		t.Errorf("default.target_ingesting_count: got %d, want 2", b.TargetIngestingCount)
	}
	if b.Tier != "small" {
		t.Errorf("default.tier: got %q, want small", b.Tier)
	}
	// apps decodes to []string via the GORM json serializer; the
	// day-1 "default" bucket is the catch-all (empty list).
	if len(b.Services) != 0 {
		t.Errorf("default.apps: got %v, want empty (catch-all)", b.Services)
	}
	// Compare as parsed durations so "168h" (migration default) and
	// "168h0m0s" (Go time.Duration.String() format, written on any
	// SaveBucket) both pass. The invariant is "7 days," not the
	// serialisation.
	want := 7 * 24 * time.Hour
	if d, err := time.ParseDuration(b.WindowDuration); err != nil || d != want {
		t.Errorf("default.window_duration: got %q (%v, err=%v), want 168h", b.WindowDuration, d, err)
	}
}

// TestBuckets_ShardsBoundToValidBuckets asserts every non-terminal
// shard's bucket_id references a real bucket row. The FK itself
// prevents orphaned references on INSERT, but this test also
// catches a more subtle regression: a shard gets bucket_id=0 (the
// zero-value) and somehow slips past the NOT NULL constraint, or a
// bucket is deleted out from under an INGESTING shard.
func TestBuckets_ShardsBoundToValidBuckets(t *testing.T) {
	db := openTestStore(t)
	defer db.Close()

	all, err := db.ListBuckets()
	if err != nil {
		t.Fatalf("ListBuckets: %v", err)
	}
	validIDs := make(map[int64]string, len(all))
	for _, b := range all {
		validIDs[b.ID] = b.Label
	}
	if len(validIDs) == 0 {
		t.Fatal("no buckets found — migration 020 did not seed 'default'")
	}

	// Give the coordinator a window to christen the docker-compose
	// shard containers' first heartbeats.
	deadline := time.Now().Add(30 * time.Second)
	var shards []store.ShardRecord
	for time.Now().Before(deadline) {
		shards, err = db.ListShards()
		if err != nil {
			t.Fatalf("ListShards: %v", err)
		}
		if len(shards) > 0 {
			break
		}
		time.Sleep(2 * time.Second)
	}
	if len(shards) == 0 {
		t.Fatal("no shards in registry after 30s — coord never christened the shard containers")
	}

	liveStates := map[string]bool{
		"LAUNCHING": true,
		"INGESTING": true,
		"READ_ONLY": true,
		"ARCHIVING": true,
	}
	checked := 0
	byBucket := make(map[int64]int)
	for _, s := range shards {
		if !liveStates[s.State] {
			continue
		}
		checked++
		if _, ok := validIDs[s.BucketID]; !ok {
			t.Errorf("shard %s state=%s bucket_id=%d is not a known bucket",
				s.ID, s.State, s.BucketID)
		}
		byBucket[s.BucketID]++
	}
	if checked == 0 {
		t.Fatalf("no non-terminal shards found among %d rows — can't assert bucket_id", len(shards))
	}
	// Log bucket attribution for context; not an assertion.
	for id, n := range byBucket {
		t.Logf("bucket %s(id=%d): %d live shards", validIDs[id], id, n)
	}
}

// TestBuckets_OnboardServicePropagates calls AddSource with a fresh app
// name, then asserts that (1) the default bucket's apps list now
// contains it, and (2) every INGESTING shard in the default bucket
// has the new app in its shard_records.apps — which is how query
// routing (hasApp) will include those shards for queries against
// this app going forward.
//
// READ_ONLY shards are a separate sub-assertion: if any exist, they
// must NOT have received the new app (the denormalization invariant
// — they can't route queries for an app they never saw writes for).
func TestBuckets_OnboardServicePropagates(t *testing.T) {
	db := openTestStore(t)
	defer db.Close()

	def, ok, err := db.GetBucketByLabel("default")
	if err != nil || !ok {
		t.Fatalf("GetBucketByLabel(default): %v / ok=%v", err, ok)
	}

	// Use a unique app name so repeated local test runs don't
	// conflict with each other's residue. The assertion is on the
	// end state (apps list CONTAINS the new one), not the full set.
	appName := fmt.Sprintf("intbuckets-%d", time.Now().UnixNano())

	conn, client := onboardGRPCClient(t)
	defer conn.Close()

	_, err = client.AddSource(context.Background(), &pb.AddSourceRequest{
		Namespace:    "kevlar",
		AwsAccountId: "000000000000",
		RoleArn:      "arn:aws:iam::000000000000:role/integration-test",
		Region:       "us-east-1",
		Service:      appName,
		LogGroup:     "/integration-test/bucket-onboarding",
		PollInterval: "30s",
	})
	if err != nil {
		t.Fatalf("AddSource: %v", err)
	}

	// Give the coordinator a tick to persist bucket + propagate to
	// shards. OnboardService is synchronous on the RPC path, but the
	// persist call goes through GORM and a test reading the DB
	// immediately after is racy in practice; retry briefly.
	deadline := time.Now().Add(10 * time.Second)
	var bucket store.Bucket
	for time.Now().Before(deadline) {
		b, ok, err := db.GetBucket(def.ID)
		if err != nil {
			t.Fatalf("GetBucket(%d): %v", def.ID, err)
		}
		if !ok {
			t.Fatal("default bucket disappeared")
		}
		if slices.Contains(b.Services, appName) {
			bucket = b
			break
		}
		time.Sleep(500 * time.Millisecond)
	}
	if bucket.ID == 0 {
		// Final read for the error message.
		b, _, _ := db.GetBucket(def.ID)
		t.Fatalf("bucket.apps missing %q after 10s: %v", appName, b.Services)
	}

	// Now check shards. Routing lives in shard_services now (migration
	// 058): each INGESTING shard bound to default must have a
	// shard_services row for the new service; READ_ONLY shards were
	// frozen at christen and must NOT have been re-stamped with it.
	shards, err := db.ListShards()
	if err != nil {
		t.Fatalf("ListShards: %v", err)
	}
	svcRows, err := db.ListShardServices()
	if err != nil {
		t.Fatalf("ListShardServices: %v", err)
	}
	servesNew := map[string]bool{} // shardID → serves appName
	for _, ss := range svcRows {
		if ss.Service == appName {
			servesNew[ss.ShardID] = true
		}
	}

	ingestingChecked := 0
	readOnlyChecked := 0
	for _, s := range shards {
		if s.BucketID != def.ID {
			continue
		}
		switch s.State {
		case "INGESTING":
			ingestingChecked++
			if !servesNew[s.ID] {
				t.Errorf("INGESTING shard %s has no shard_services row for service %q",
					s.ID, appName)
			}
		case "READ_ONLY":
			readOnlyChecked++
			if servesNew[s.ID] {
				t.Errorf("READ_ONLY shard %s was re-stamped with service %q (christen stamp must be frozen)",
					s.ID, appName)
			}
		}
	}
	if ingestingChecked == 0 {
		t.Fatal("no INGESTING shards found in default bucket — can't verify propagation")
	}
	t.Logf("verified %d INGESTING shards received %q; %d READ_ONLY shards stayed frozen",
		ingestingChecked, appName, readOnlyChecked)
}
